const connection = msg.payload;
const clients    = Object.values(connection.clients);
const target     = clients.find(c => c.client_system === "wasos");
const source     = clients.find(c => c.client_system !== "wasos");

msg.topic    = source.client_system;
msg.metadata = {
    source:     source,
    target:     target,
    connection_name: connection.name
};

return msg;

return {
    _msgid: msg._msgid,
    topic: "new_message",
    entry: {
        id:        msg.payload.id,
        text:      msg.payload.text,
        timestamp: msg.payload.timestamp,
        author:    msg.payload.author,
        files:     msg.payload.files,
        labels:    msg.payload.labels,
        metadata:  msg.metadata
    }
};

/**             
 * Annotates each entry with whether it is the last position event
 * for its delhendelse. Only the last one should trigger a geo POST,                                                                                                
 * preventing duplicate markers during initial batch processing.                                                                                                    
 */
const regex = /Posisjonen til delhendelsen '(.+?)' ble endret til/s;
const lastIndex = {};

msg.payload.forEach((entry, idx) => {
    if (entry.text) {
        const match = entry.text.match(regex);
        if (match) lastIndex[match[1]] = idx;
    }
});

msg.payload.forEach((entry, idx) => {
    if (entry.text) {
        const match = entry.text.match(regex);
        if (match) entry._is_last_geo = (lastIndex[match[1]] === idx);
    }
});

return msg;
